export const Escena:React.FC=()=>{const {s}=useS();let i=0;START.forEach((t,j)=>{if(s>=t)i=j});const next=i+1<START.length&&s>START[i+1]-.28;const prev=i>0&&s<START[i]+.28;const j=next?i+1:prev?i:-1;
 return <AbsoluteFill style={{background:tono(s,[START[0],START[5],START[6],START[11]],['#d9a384','#774a76','#263c43','#d9a384'])}}>{j>0?<Paso t={START[j]} tipo={j===5?'barrido':j===10?'alejar':j===11?'forma':j%2?'alejar':'forma'} dur={.45} x={540} y={1080} antes={<Scene i={j-1}/>} despues={<Scene i={j}/>}/>:<Scene i={i}/>}</AbsoluteFill>;
};
