 {t:en('cebolla')+.15,s:'papel_01'},{t:en('gas')+.14,s:'whoosh_02'},{t:en('emoción')+.14,s:'chime_01'},
 {t:en('sobran')+.14,s:'whoosh_03'},{t:en('huequito')+.14,s:'ding_03'},{t:en('tubito')+.13,s:'whoosh_04'},
 {t:en('moquea')+.14,s:'pop_03'},{t:en('nota')+.14,s:'pop_02'},{t:en('basurita')+.13,s:'pop_01'}];
